bounded_host_request.command:
set -euo pipefail
docker run --rm --network host --pull never --read-only --cap-drop ALL \
 --security-opt no-new-privileges:true --entrypoint node \
 create-videobot:local-poll --input-type=module -e '
import {setDefaultResultOrder} from "node:dns";
import {setDefaultAutoSelectFamily} from "node:net";
setDefaultResultOrder("ipv4first");
setDefaultAutoSelectFamily(false);
try{
 const r=await fetch("https://api.telegram.org",{signal:AbortSignal.timeout(12000)});
 process.exitCode=r.status>=200&&r.status<500?0:80;
}catch(e){
 const c=String(e?.cause?.code??e?.code??"");
 process.exitCode=c==="UND_ERR_CONNECT_TIMEOUT"?81:
  c==="ETIMEDOUT"?82:
  c==="ENOTFOUND"?83:
  c==="ENETUNREACH"?84:85;
}'
